import { z } from 'zod';

/**
 * Lesson and teaching script data models & Zod runtime validation schemas.
 * Represents the complete, structured educational lesson output generated by the AI Engine.
 */

// ─── Source Reference Schema ───────────────────────────────────

export const ChapterSourceReferenceSchema = z.object({
  blockId: z.string().optional().nullable(),
  pageNumber: z.number().optional().nullable(),
  sectionTitle: z.string().optional().nullable(),
});

export type ChapterSourceReference = z.infer<typeof ChapterSourceReferenceSchema>;

// ─── Key Concept Schema ────────────────────────────────────────

export const KeyConceptSchema = z.object({
  name: z.string().min(1, 'Concept name is required'),
  explanation: z.string().min(1, 'Concept explanation is required'),
  sourceReferences: z.array(z.string()).default([]),
});

export type KeyConcept = z.infer<typeof KeyConceptSchema>;

// ─── Chapter Schema ────────────────────────────────────────────

export const LessonChapterSchema = z.object({
  id: z.string().min(1, 'Chapter ID is required'),
  index: z.number().int().positive().optional(),
  title: z.string().min(1, 'Chapter title is required'),
  overview: z.string().min(1, 'Chapter overview is required'),
  conceptsCovered: z.array(z.string()).default([]),
  teachingScript: z.string().min(10, 'Teaching script must be substantive'),
  transitionToNext: z.string().default(''),
  sourceReferences: z.array(ChapterSourceReferenceSchema).default([]),
  estimatedDurationSeconds: z.number().optional(),
});

export type LessonChapter = z.infer<typeof LessonChapterSchema>;

// ─── Document Understanding Schema ────────────────────────────

export const DocumentUnderstandingSchema = z.object({
  subject: z.string().min(1, 'Subject is required'),
  purpose: z.string().min(1, 'Purpose is required'),
  learningObjective: z.string().min(1, 'Learning objective is required'),
  mainTopics: z.array(z.string()).min(1, 'At least one main topic is required'),
  keyConcepts: z.array(KeyConceptSchema).default([]),
  terminology: z.array(z.object({
    term: z.string(),
    definition: z.string(),
  })).default([]),
  relationshipsBetweenConcepts: z.array(z.string()).default([]),
  relationshipsBetweenSections: z.array(z.string()).default([]),
  importantExamples: z.array(z.string()).default([]),
  importantFormulasOrNumbers: z.array(z.string()).default([]),
  prerequisites: z.array(z.string()).default([]),
});

export type DocumentUnderstanding = z.infer<typeof DocumentUnderstandingSchema>;

// ─── Validation Result Schema ─────────────────────────────────

export const UnsupportedClaimItemSchema = z.object({
  claim: z.string(),
  chapterId: z.string().optional(),
  reason: z.string(),
  severity: z.enum(['warning', 'discrepancy']),
});

export type UnsupportedClaimItem = z.infer<typeof UnsupportedClaimItemSchema>;

export const LessonValidationSchema = z.object({
  sourceCoverage: z.enum(['passed', 'partial', 'failed']).default('passed'),
  coverageScore: z.number().min(0).max(1).default(1),
  unsupportedClaims: z.array(UnsupportedClaimItemSchema).default([]),
  warnings: z.array(z.string()).default([]),
  coveredSectionTitles: z.array(z.string()).default([]),
  missingSectionTitles: z.array(z.string()).default([]),
});

export type LessonValidation = z.infer<typeof LessonValidationSchema>;

// ─── Complete Generated Lesson Schema ──────────────────────────

export const GeneratedLessonSchema = z.object({
  id: z.string().default(() => `lesson-${Date.now()}`),
  documentTitle: z.string().min(1, 'Document title is required'),
  subject: z.string().min(1, 'Subject is required'),
  purpose: z.string().min(1, 'Purpose is required'),
  lessonOverview: z.string().min(1, 'Lesson overview is required'),
  keyConcepts: z.array(KeyConceptSchema).default([]),
  chapters: z.array(LessonChapterSchema).min(1, 'At least one chapter must be generated'),
  completeLessonScript: z.string().min(20, 'Complete lesson script is required'),
  validation: LessonValidationSchema.default({
    sourceCoverage: 'passed',
    coverageScore: 1,
    unsupportedClaims: [],
    warnings: [],
    coveredSectionTitles: [],
    missingSectionTitles: [],
  }),
  createdAt: z.string().default(() => new Date().toISOString()),
});

export type GeneratedLesson = z.infer<typeof GeneratedLessonSchema>;

// Alias for backwards/forward compatibility with other phases
export type Lesson = GeneratedLesson;
